      "rank": 1,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed frequency metrology into a sensitive probe of time, gravity and fundamental physics.",
        "attribution": "Katori introduced the decisive lattice-clock concept; Ye made comparably foundational experimental advances toward record performance.",
        "maturity": "Independent laboratories now reproducibly operate clocks at and beyond the stated precision, with broad scientific use.",
        "uncertainties": []
      }
    },
    {
      "rank": 2,
      "ballot_id": "B036",
      "proposed_laureates": [
        "Fedor Jelezko",
        "Jörg Wrachtrup",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Single-spin diamond optics created an unusually powerful platform for quantum control and nanoscale sensing.",
        "attribution": "Jelezko and Wrachtrup established crucial single-NV experiments, while Lukin made defining contributions to coherent control and quantum-network applications.",
        "maturity": "The measurements are robust and have spread widely into sensing, imaging and quantum-information experiments.",
        "uncertainties": [
          "The historical credit boundary between early diamond-spin spectroscopy and later quantum-control work needs careful reconstruction."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B010",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped ions supplied a remarkably clean, controllable realization of quantum computation and simulation.",
        "attribution": "Cirac and Zoller supplied seminal architectures and protocols; Blatt gave sustained experimental realization at high fidelity.",
        "maturity": "Decades of replicated experiments demonstrate entanglement, gates, algorithms and simulations with steadily improving control.",
        "uncertainties": [
          "The contribution overlaps a broad international development of trapped-ion quantum information."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B011",
      "proposed_laureates": [
        "Peter F. Moulton",
        "Ursula Keller",
        "Wilson Sibbett"
      ],
      "assessment": {
        "nobel_worthiness": "The practical femtosecond laser became an enabling instrument across precision science, spectroscopy, chemistry and medicine.",
        "attribution": "Moulton's titanium-sapphire laser and Keller's Kerr-lens and saturable-absorber advances are central; Sibbett was pivotal in practical ultrafast laser development.",
        "maturity": "The methods have been standard, reproducible laboratory and commercial technology for many years.",
        "uncertainties": [
          "Credit for passive mode locking is distributed across several important experimental groups."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B040",
      "proposed_laureates": [
        "Christian J. Bordé",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry furnished extraordinarily precise quantum sensors and powerful tests of gravitation and quantum mechanics.",
        "attribution": "Bordé laid essential theoretical and experimental foundations; Kasevich drove landmark light-pulse interferometric measurements and applications.",
        "maturity": "The technique is established across many laboratories and has delivered exceptionally precise inertial and gravitational measurements.",
        "uncertainties": [
          "Assigning a small laureate set across the broad foundational development is difficult."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Hoi-Kwong Lo",
        "Jian-Wei Pan"
      ],
      "assessment": {
        "nobel_worthiness": "Decoy-state protocols and long-distance satellite experiments made quantum communication an experimentally credible global technology.",
        "attribution": "Lo is strongly associated with the decoy-state breakthrough, and Pan led exceptional demonstrations of entanglement distribution and teleportation.",
        "maturity": "The underlying protocols and optical links have been independently tested, though a mature general-purpose quantum network remains unfinished.",
        "uncertainties": [
          "This work is closely connected to earlier foundational quantum-cryptography contributions."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Federico Capasso",
        "Jérôme Faist"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum cascade lasers established a new semiconductor-laser principle with major impact in mid-infrared and terahertz spectroscopy.",
        "attribution": "Faist and Capasso were decisive in conception and first realization; Cho's heterostructure technology was an important enabling antecedent.",
        "maturity": "The devices are a long-established, versatile technology used in precision chemical sensing and other applications.",
        "uncertainties": [
          "The relative scope of conceptual versus materials-enabling credit should be reviewed."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Markus Aspelmeyer",
        "Oskar Painter",
        "Tobias J. Kippenberg"
      ],
      "assessment": {
        "nobel_worthiness": "Cavity optomechanics brought engineered mechanical motion into the quantum regime and opened a rich interface between light, motion and sensing.",
        "attribution": "Aspelmeyer, Painter and Kippenberg each made central experimental and conceptual contributions to the modern field.",
        "maturity": "Ground-state cooling, quantum measurement and coherent control are established experimentally, with growing sensing relevance.",
        "uncertainties": [
          "The field remains comparatively young, and the optimal attribution among several foundational groups is unsettled."
        ]
      }
    }
  ]
}
